using BARANG.Core.Domain.Catalog; using BARANG.Core.Domain.Organization; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;  namespace BARANG.Core.Infrastructure.Persistence.Configurations;  internal static class CatalogConfiguration {     internal static void Base<T>(EntityTypeBuilder<T> builder, string table) where T : CatalogEntity     {         builder.ToTable(table, t => t.HasCheckConstraint($"ck_{table}_version_positive", "version > 0"));         builder.HasKey(x => x.Id).HasName($"pk_{table}");         builder.Property(x => x.Id).HasColumnName("id").ValueGeneratedNever();         builder.Property(x => x.CompanyId).HasColumnName("company_id");         builder.Property(x => x.IsActive).HasColumnName("is_active");         builder.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc");         builder.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc");         builder.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken();         builder.HasOne<Company>().WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Restrict);         builder.HasAlternateKey(x => new { x.CompanyId, x.Id }).HasName($"ak_{table}_company_id_id");     } }  internal sealed class ProductConfiguration : IEntityTypeConfiguration<Product> {     public void Configure(EntityTypeBuilder<Product> b)     {         CatalogConfiguration.Base(b, "products");         b.Property(x => x.ProductCode).HasColumnName("product_code").HasMaxLength(50);         b.Property(x => x.Name).HasColumnName("name").HasMaxLength(200);         b.Property(x => x.Description).HasColumnName("description").HasMaxLength(2000);         b.Property(x => x.ProductTypeCode).HasColumnName("product_type_code").HasMaxLength(50);         b.Property(x => x.UnitOfMeasureCode).HasColumnName("unit_of_measure_code").HasMaxLength(30);         b.HasIndex(x => new { x.CompanyId, x.ProductCode }).IsUnique().HasDatabaseName("uq_products_company_code");         b.HasIndex(x => new { x.CompanyId, x.IsActive, x.ProductCode }).HasDatabaseName("ix_products_directory");         b.HasIndex(x => new { x.CompanyId, x.Name }).HasDatabaseName("ix_products_company_name");     } }  internal sealed class ProductVariantConfiguration : IEntityTypeConfiguration<ProductVariant> {     public void Configure(EntityTypeBuilder<ProductVariant> b)     {         CatalogConfiguration.Base(b, "product_variants");         b.Property(x => x.ProductId).HasColumnName("product_id");         b.Property(x => x.Sku).HasColumnName("sku").HasMaxLength(80);         b.Property(x => x.DisplayName).HasColumnName("display_name").HasMaxLength(200);         b.Property(x => x.Barcode).HasColumnName("barcode").HasMaxLength(100);         b.Property(x => x.SizeCode).HasColumnName("size_code").HasMaxLength(50);         b.Property(x => x.ColorCode).HasColumnName("color_code").HasMaxLength(50);         b.HasOne<Product>().WithMany().HasForeignKey(x => new { x.CompanyId, x.ProductId }).HasPrincipalKey(x => new { x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasAlternateKey(x => new { x.CompanyId, x.ProductId, x.Id }).HasName("ak_product_variants_company_product_id");         b.HasIndex(x => new { x.CompanyId, x.Sku }).IsUnique().HasDatabaseName("uq_product_variants_company_sku");         b.HasIndex(x => new { x.CompanyId, x.Barcode }).HasFilter("barcode IS NOT NULL").IsUnique().HasDatabaseName("uq_product_variants_company_barcode");         b.HasIndex(x => new { x.CompanyId, x.ProductId, x.IsActive, x.Sku }).HasDatabaseName("ix_product_variants_product_directory");     } }  internal sealed class SupplierConfiguration : IEntityTypeConfiguration<Supplier> {     public void Configure(EntityTypeBuilder<Supplier> b)     {         CatalogConfiguration.Base(b, "suppliers");         b.Property(x => x.SupplierCode).HasColumnName("supplier_code").HasMaxLength(50);         b.Property(x => x.DisplayName).HasColumnName("display_name").HasMaxLength(200);         b.Property(x => x.LegalName).HasColumnName("legal_name").HasMaxLength(200);         b.Property(x => x.RegistrationNo).HasColumnName("registration_no").HasMaxLength(64);         b.Property(x => x.TaxId).HasColumnName("tax_id").HasMaxLength(64);         b.Property(x => x.PrimaryEmail).HasColumnName("primary_email").HasMaxLength(320);         b.Property(x => x.PrimaryPhone).HasColumnName("primary_phone").HasMaxLength(16);         b.Property(x => x.PrimaryMobile).HasColumnName("primary_mobile").HasMaxLength(16);         b.Property(x => x.Website).HasColumnName("website").HasMaxLength(500);         b.Property(x => x.Notes).HasColumnName("notes").HasMaxLength(2000);         b.HasIndex(x => new { x.CompanyId, x.SupplierCode }).IsUnique().HasDatabaseName("uq_suppliers_company_code");         b.HasIndex(x => new { x.CompanyId, x.IsActive, x.SupplierCode }).HasDatabaseName("ix_suppliers_directory");         b.HasIndex(x => new { x.CompanyId, x.DisplayName }).HasDatabaseName("ix_suppliers_company_name");         SupplierCoreConfiguration.Supplier(b);     } }  internal sealed class SupplierProductConfiguration : IEntityTypeConfiguration<SupplierProduct> {     public void Configure(EntityTypeBuilder<SupplierProduct> b)     {         CatalogConfiguration.Base(b, "supplier_products");         b.ToTable("supplier_products", t => { t.HasCheckConstraint("ck_supplier_products_version_positive", "version > 0"); t.HasCheckConstraint("ck_supplier_products_moq_nonnegative", "minimum_order_quantity IS NULL OR minimum_order_quantity >= 0"); t.HasCheckConstraint("ck_supplier_products_lead_nonnegative", "lead_time_days IS NULL OR lead_time_days >= 0"); });         b.Property(x => x.SupplierId).HasColumnName("supplier_id"); b.Property(x => x.ProductId).HasColumnName("product_id"); b.Property(x => x.ProductVariantId).HasColumnName("product_variant_id");         b.Property(x => x.SupplierItemCode).HasColumnName("supplier_item_code").HasMaxLength(80); b.Property(x => x.IsPreferred).HasColumnName("is_preferred"); b.Property(x => x.MinimumOrderQuantity).HasColumnName("minimum_order_quantity").HasPrecision(18, 4); b.Property(x => x.LeadTimeDays).HasColumnName("lead_time_days");         b.HasOne<Supplier>().WithMany().HasForeignKey(x => new { x.CompanyId, x.SupplierId }).HasPrincipalKey(x => new { x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasOne<Product>().WithMany().HasForeignKey(x => new { x.CompanyId, x.ProductId }).HasPrincipalKey(x => new { x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasOne<ProductVariant>().WithMany().HasForeignKey(x => new { x.CompanyId, x.ProductId, x.ProductVariantId }).HasPrincipalKey(x => new { x.CompanyId, x.ProductId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasIndex(x => new { x.CompanyId, x.SupplierId, x.ProductId }).HasFilter("product_variant_id IS NULL").IsUnique().HasDatabaseName("uq_supplier_products_product_level");         b.HasIndex(x => new { x.CompanyId, x.SupplierId, x.ProductVariantId }).HasFilter("product_variant_id IS NOT NULL").IsUnique().HasDatabaseName("uq_supplier_products_variant_level");         b.HasIndex(x => new { x.CompanyId, x.ProductId, x.IsPreferred, x.IsActive }).HasDatabaseName("ix_supplier_products_product");     } }  internal sealed class EquipmentConfiguration : IEntityTypeConfiguration<Equipment> {     public void Configure(EntityTypeBuilder<Equipment> b)     {         CatalogConfiguration.Base(b, "equipment");         b.Property(x => x.EquipmentCode).HasColumnName("equipment_code").HasMaxLength(50); b.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); b.Property(x => x.EquipmentTypeCode).HasColumnName("equipment_type_code").HasMaxLength(50); b.Property(x => x.OperationalStatusCode).HasColumnName("operational_status_code").HasMaxLength(50);         b.Property(x => x.BranchId).HasColumnName("branch_id"); b.Property(x => x.OrganizationalUnitId).HasColumnName("organizational_unit_id"); b.Property(x => x.Description).HasColumnName("description").HasMaxLength(2000); b.Property(x => x.Manufacturer).HasColumnName("manufacturer").HasMaxLength(150); b.Property(x => x.Model).HasColumnName("model").HasMaxLength(150); b.Property(x => x.SerialNumber).HasColumnName("serial_number").HasMaxLength(150);         b.HasOne<Branch>().WithMany().HasForeignKey(x => new { x.CompanyId, x.BranchId }).HasPrincipalKey(x => new { x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasOne<OrganizationalUnit>().WithMany().HasForeignKey(x => new { x.CompanyId, x.OrganizationalUnitId }).HasPrincipalKey(x => new { x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Restrict);         b.HasIndex(x => new { x.CompanyId, x.EquipmentCode }).IsUnique().HasDatabaseName("uq_equipment_company_code");         b.HasIndex(x => new { x.CompanyId, x.IsActive, x.EquipmentTypeCode, x.OperationalStatusCode }).HasDatabaseName("ix_equipment_directory");         b.HasIndex(x => new { x.CompanyId, x.BranchId }).HasDatabaseName("ix_equipment_branch");     } }
